"""rotate (docs/rotate.md) and policy.ini (docs/policy.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, state, streams
from logkeep.errors import DataError, Refused

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": timedelta(0),
           "compress_after": 1, "keep": 5, "keep_days": None}
KEYS = set(BUILTIN)
_SECTION = re.compile(r"\[(?:(defaults)|stream ([a-z][a-z0-9_-]*))\]\Z")
_INT = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_TIME_Z = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})\Z")
_TIME_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_NUM = re.compile(r"(NAME)\.log\.([1-9][0-9]*)(\.gz)?\Z")


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if v == "off" and key in ("max_size", "max_age", "keep_days"):
        return None
    if key == "max_size":
        m = _SIZE.match(v)
        if not m:
            raise _bad(f"bad size {v}")
        return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    if key == "max_age":
        m = _DUR.match(v)
        if not m:
            raise _bad(f"bad duration {v}")
        return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})
    if key == "naming":
        if v not in ("numbered", "dated"):
            raise _bad(f"bad naming {v}")
        return v
    if key == "offset":
        m = _OFF.match(v)
        if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
            raise _bad(f"bad offset {v}")
        d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
        return -d if m.group(1) == "-" else d
    if not _INT.match(v):
        raise _bad(f"bad number {v}")
    n = int(v)
    if key in ("keep", "keep_days") and n < 1:
        raise _bad(f"{key} must be 1 or more")
    return n


def load_policy(path):
    """Returns (defaults dict, {stream: dict}) of parsed values."""
    defaults, per = {}, {}
    if not path.exists():
        return defaults, per
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    cur = None
    seen_def = False
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            m = _SECTION.match(line)
            if not m:
                raise _bad(f"bad section {line}")
            if m.group(1):
                if seen_def:
                    raise _bad("defaults twice")
                seen_def = True
                cur = defaults
            else:
                if m.group(2) in per:
                    raise _bad("section twice")
                cur = per[m.group(2)] = {}
            continue
        if cur is None or "=" not in line:
            raise _bad(f"bad line {line}")
        k, v = (s.strip() for s in line.split("=", 1))
        if k not in KEYS or k in cur:
            raise _bad(f"bad or repeated key {k}")
        cur[k] = _value(k, v)
    return defaults, per


def parse_time(s):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(s, str):
        return None
    try:
        if _TIME_Z.match(s):
            t = datetime.fromisoformat(s)
        elif _TIME_OLD.match(s):
            t = datetime.fromisoformat(s).replace(tzinfo=timezone.utc)
        else:
            return None
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def _check_state(doc, existing):
    for name in existing:
        e = doc["streams"].get(name)
        if e is None:
            continue
        if "opened" in e and parse_time(e["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "rotations" in e:
            r = e["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: bad rotations")
        if "archives" in e:
            a = e["archives"]
            if not isinstance(a, dict):
                raise DataError("state", f"{name}: bad archives")
            for k, v in a.items():
                if parse_time(v) is None:
                    raise DataError("state", f"{name}: bad archive time {k}")


def _parse_archive(name, fname, naming):
    """Returns (sortkey, gz) or None."""
    pre = f"{name}.log."
    if not fname.startswith(pre):
        return None
    rest = fname[len(pre):]
    gz = rest.endswith(".gz")
    if gz:
        rest = rest[:-3]
    if naming == "numbered":
        if re.fullmatch(r"[1-9][0-9]*", rest):
            return (-int(rest),), gz, rest
        return None
    m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?", rest)
    if not m:
        return None
    try:
        d = date.fromisoformat(m.group(1))
    except ValueError:
        return None
    return (d.toordinal(), int(m.group(2) or 1)), gz, rest


def _first_time(path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    tok = text.split(" ", 1)[0]
    return parse_time(tok) if _TIME_Z.match(tok) else None


def run(ctx, names, dry, force):
    data = ctx.data
    defaults, per = load_policy(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(data)) | set(per)
    _check_state(doc, existing)
    if names:
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        todo = sorted(set(names))
    else:
        todo = sorted(existing)
    ldir = streams.logs_dir(data)
    files = {p.name for p in ldir.iterdir() if p.is_file()} if ldir.is_dir() else set()

    plans = []
    for name in todo:
        pol = dict(BUILTIN)
        pol.update(defaults)
        pol.update(per.get(name, {}))
        arcs = {}
        for f in files:
            r = _parse_archive(name, f, pol["naming"])
            if r is None:
                continue
            key, gz, _ = r
            if key in arcs:
                raise DataError("archives", f"{name}: two archives in the same place")
            arcs[key] = {"key": key, "old": f, "gz": gz, "new": False}
        plans.append((name, pol, arcs))

    now = ctx.now
    out, newstreams = [], {}
    nrot = nrem = ncomp = 0
    ops = []  # (action, ...)
    for name, pol, arcs in plans:
        entry = doc["streams"].get(name, {})
        times = {k: parse_time(v) for k, v in entry.get("archives", {}).items()}
        log = streams.log_path(data, name)
        why = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, why = "forced", True
            elif pol["max_size"] is not None and size >= pol["max_size"]:
                what, why = "size", True
            else:
                what = "not due"
                if pol["max_age"] is not None:
                    opened = parse_time(entry["opened"]) if "opened" in entry else _first_time(log)
                    if opened is not None and now - opened >= pol["max_age"]:
                        what, why = "age", True
        rotated = bool(why)
        items = list(arcs.values())
        if rotated:
            if pol["naming"] == "numbered":
                key = (0,)
                newname = None
                rest = None
                item = {"key": (1,), "old": None, "gz": False, "new": True}
                for it in items:
                    it["key"] = (it["key"][0] - 1,)
                items.append(item)
            else:
                day = now.astimezone(timezone(pol["offset"])).date()
                ks = [it["key"][1] for it in items if it["key"][0] == day.toordinal()]
                k = max(ks) + 1 if ks else 1
                items.append({"key": (day.toordinal(), k), "old": None, "gz": False, "new": True})
        items.sort(key=lambda it: it["key"], reverse=True)
        if pol["naming"] == "numbered":
            items.sort(key=lambda it: it["key"], reverse=True)
        # newest first: for numbered, keys are -N so larger key = newer
        for pos, it in enumerate(items, 1):
            it["pos"] = pos
            if it["new"]:
                t = now
            else:
                t = times.get(it["old"])
            it["time"] = t
            it["remove"] = pos > pol["keep"] or (pol["keep_days"] is not None and t is not None and
                                                 now - t >= timedelta(days=pol["keep_days"]))
        kept = [it for it in items if not it["remove"]]
        for pos, it in enumerate(kept, 1):
            it["compress"] = (not it["gz"]) and pos > pol["compress_after"]
            gz = it["gz"] or it["compress"]
            if pol["naming"] == "numbered":
                base = str(pos)
            else:
                d = date.fromordinal(it["key"][0]).isoformat()
                base = d if it["key"][1] == 1 else f"{d}.{it['key'][1]}"
            it["final"] = f"{name}.log.{base}" + (".gz" if gz else "")
        out.append(f"{name}: " + (f"rotate ({what})" if rotated else what))
        for it in kept:
            if it["new"]:
                out.append(f"  new {it['final']}")
            elif it["final"] != it["old"]:
                out.append(f"  {it['final']} <- {it['old']}")
            else:
                out.append(f"  {it['final']}")
            if it["compress"]:
                ncomp += 1
        for it in items:
            if it["remove"]:
                out.append(f"  remove {it['old'] or '(new)'}")
        nrot += rotated
        nrem += sum(1 for it in items if it["remove"])
        # fix removal of a new archive: name it by what it would have been
        ops.append((name, log, rotated, items))
        newstreams[name] = (entry, rotated, kept)
    # second pass for the "remove" names of new archives is handled above in output
    out.append(f"{nrot} rotated, {nrem} removed, {ncomp} compressed")
    if dry:
        out.append("dry run: nothing written")
        return out

    # build the new state first (nothing is written until here)
    for name, (entry, rotated, kept) in newstreams.items():
        e = {}
        if rotated:
            e["opened"] = ctx.stamp
        elif "opened" in entry:
            e["opened"] = entry["opened"]
        e["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        arch = {}
        old_times = entry.get("archives", {})
        for it in kept:
            if it["new"]:
                arch[it["final"]] = ctx.stamp
            elif it["old"] in old_times:
                arch[it["final"]] = old_times[it["old"]]
        e["archives"] = arch
        doc["streams"][name] = e

    for name, log, rotated, items in ops:
        contents = {}
        for it in items:
            if it["new"]:
                if not it["remove"]:
                    raw = log.read_bytes()
                    contents[it["final"]] = gzip.compress(raw, mtime=0) if it["compress"] else raw
            elif it["remove"]:
                (ldir / it["old"]).unlink()
            elif it["final"] != it["old"]:
                raw = (ldir / it["old"]).read_bytes()
                contents[it["final"]] = gzip.compress(raw, mtime=0) if it["compress"] else raw
                (ldir / it["old"]).unlink()
        for fname, raw in contents.items():
            (ldir / fname).write_bytes(raw)
        if rotated:
            log.write_bytes(b"")
    state.save(ctx.state_path, doc)
    return out
